func (t *pckTransport) Dial(int) (net.Conn, error) { return nil, fmt.Errorf("tcp+pck is Linux only") }
func (t *pckTransport) Accept() (net.Conn, error)  { return nil, fmt.Errorf("tcp+pck is Linux only") }
